package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type DocumentSearchResult struct {
	ID        int    `json:"id"`
	Title     string `json:"title"`
	Classification string `json:"classification"`
	Content   string `json:"content"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Limit length to prevent buffer issues
	if len(input) > 200 {
		input = input[:200]
	}
	return input
}

// classificationFilter returns SQL clause based on user clearance
func classificationFilter(clearance string) string {
	switch clearance {
	case "TOP_SECRET":
		return "classification IN ('UNCLASSIFIED','CONFIDENTIAL','SECRET','TOP_SECRET')"
	case "SECRET":
		return "classification IN ('UNCLASSIFIED','CONFIDENTIAL','SECRET')"
	case "CONFIDENTIAL":
		return "classification IN ('UNCLASSIFIED','CONFIDENTIAL')"
	default:
		return "classification = 'UNCLASSIFIED'"
	}
}

func searchDocuments(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var body struct {
		Query     string `json:"query"`
		Category  string `json:"category"`
		Clearance string `json:"clearance"`
	}

	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	body.Query = sanitizeInput(body.Query)
	body.Category = sanitizeInput(body.Category)

	// Build search query with full-text search
	classFilter := classificationFilter(body.Clearance)

	// The category filter uses parameterized approach for the main query
	// but constructs an ORDER BY clause dynamically for relevance scoring
	var sqlQuery string
	if body.Category != "" {
		// Category-filtered search with relevance ordering
		sqlQuery = fmt.Sprintf(
			`SELECT id, title, classification, content 
			 FROM documents 
			 WHERE %s 
			   AND category = $1 
			   AND to_tsvector('english', content) @@ plainto_tsquery('english', $2)
			 ORDER BY ts_rank(to_tsvector('english', content), plainto_tsquery('english', '%s')) DESC
			 LIMIT 20`,
			classFilter, body.Query)
	} else {
		sqlQuery = fmt.Sprintf(
			`SELECT id, title, classification, content 
			 FROM documents 
			 WHERE %s 
			   AND to_tsvector('english', content) @@ plainto_tsquery('english', $1)
			 ORDER BY ts_rank(to_tsvector('english', content), plainto_tsquery('english', '%s')) DESC
			 LIMIT 20`,
			classFilter, body.Query)
	}

	var rows *sql.Rows
	var err error
	if body.Category != "" {
		rows, err = db.Query(sqlQuery, body.Category, body.Query)
	} else {
		rows, err = db.Query(sqlQuery, body.Query)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Search failed", 500)
		return
	}
	defer rows.Close()

	var results []DocumentSearchResult
	for rows.Next() {
		var doc DocumentSearchResult
		if err := rows.Scan(&doc.ID, &doc.Title, &doc.Classification, &doc.Content); err != nil {
			continue
		}
		results = append(results, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/documents/search", searchDocuments)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
